// Build the single-file bundle: backend + embedded frontend (base64).
//   node scripts/build-bundle.mjs
// Output: bundle/pdnsdash.js (no node_modules needed at runtime)
import * as esbuild from "esbuild";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const DIST = path.join(ROOT, "frontend", "dist");
const GENERATED = path.join(ROOT, "backend", "src", "frontend-files.js");
const OUT = path.join(ROOT, "bundle");

if (!fs.existsSync(path.join(DIST, "index.html"))) {
  console.error("frontend/dist chưa build — chạy: cd frontend && npm run build");
  process.exit(1);
}

// 1. Embed frontend/dist as base64 map
const files = {};
const walk = (dir, prefix = "") => {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const rel = `${prefix}/${entry.name}`;
    if (entry.isDirectory()) walk(path.join(dir, entry.name), rel);
    else files[rel] = fs.readFileSync(path.join(dir, entry.name)).toString("base64");
  }
};
walk(DIST);
fs.writeFileSync(
  GENERATED,
  `// GENERATED by scripts/build-bundle.mjs — do not edit\nexport const FILES = ${JSON.stringify(files)};\n`
);
console.log(`Embedded ${Object.keys(files).length} frontend files`);

// 2. Bundle backend to a single ESM file
await esbuild.build({
  entryPoints: [path.join(ROOT, "backend", "src", "index.js")],
  bundle: true,
  platform: "node",
  format: "esm",
  target: "node22",
  outfile: path.join(OUT, "pdnsdash.js"),
  banner: {
    js: 'import { createRequire } from "node:module"; const require = createRequire(import.meta.url);',
  },
});

const size = fs.statSync(path.join(OUT, "pdnsdash.js")).size;
console.log(`Bundle: bundle/pdnsdash.js (${(size / 1024).toFixed(0)} KB)`);
